import json

# Try to find exchange rate data in the 1964 JSON file
with open('/app/resources/treasury_bulletin_1964_04.json', 'r') as f:
    data = json.load(f)

# Search through elements for exchange rate related content
def search_for_exchange(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            new_path = f"{path}.{key}" if path else key
            if 'exchange' in str(key).lower() or 'pound' in str(key).lower() or 'gbp' in str(key).lower() or 'rate' in str(key).lower():
                results.append((new_path, value))
            results.extend(search_for_exchange(value, new_path))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_for_exchange(item, f"{path}[{i}]"))
    return results

results = search_for_exchange(data)
for path, value in results[:20]:
    print(f"{path}: {value}")
