import json

# Search the 1964 JSON more thoroughly
with open('/as корпу念/resources/treasury_bulletin_1964_04.json', 'r') as f:
    data = json.load(f)

# Search through all elements
def find_text_content(obj, depth=0):
    results = []
    if depth > 10:
        return results
    if isinstance(obj, dict):
        if 'content' in obj and obj.get('content'):
            content = obj['content']
            if isinstance(content, str) and len(content) > 10:
                results.append(content[:200])
        for key, value in obj.items():
            results.extend(find_text_content(value, depth+1))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(find_text_content(item, depth+1))
    return results

# Get all text content
all_text = find_text_content(data)
for text in all_text:
    if 'exchange' in text.lower() or 'pound' in text.lower():
        print(text[:500])
        print("---")
